    "heroImage": "https://www.themealdb.com/images/media/meals/uquqtu1511178042.jpg",
    "heroAlt": "Fettucine alfredo, a Italian dish",
    "intro": "An Italian pasta dish. In a medium saucepan, stir the clotted cream, butter and cornflour over a low-ish heat and bring to a low simmer. Turn off the heat and keep warm.",
    "ingredients": [
      {
        "quantity": 227,
        "unit": "g",
        "item": "Clotted Cream",
        "pantry": false
      },
      {
        "quantity": 25,
        "unit": "g",
        "item": "Butter",
        "pantry": false
      },
      {
        "quantity": 1,
        "unit": "tsp",
        "item": "Corn Flour",
        "pantry": false
      },
      {
        "quantity": 100,
        "unit": "g",
        "item": "Parmesan Cheese",
        "pantry": false
      },
      {
        "quantity": null,
        "unit": "Grated",
        "item": "Nutmeg",
        "pantry": false
      },
      {
        "quantity": 250,
        "unit": "g",
        "item": "Fettuccine",
        "pantry": false
      },
      {
        "quantity": null,
        "unit": "Chopped",
        "item": "Parsley",
        "pantry": false
      }
    ],
    "steps": [
      {
        "instruction": "In a medium saucepan, stir the clotted cream, butter and cornflour over a low-ish heat and bring to a low simmer. Turn off the heat and keep warm."
      },
      {
        "instruction": "Meanwhile, put the cheese and nutmeg in a small bowl and add a good grinding of black pepper, then stir everything together (don't add any salt at this stage)."
      },
      {
        "instruction": "Put the pasta in another pan with 2 tsp salt, pour over some boiling water and cook following pack instructions (usually 3-4 mins). When cooked, scoop some of the cooking water into a heatproof jug or mug and drain the pasta, but not too thoroughly."
      },
      {
        "instruction": "Add the pasta to the pan with the clotted cream mixture, then sprinkle over the cheese and gently fold everything together over a low heat using a rubber spatula. When combined, splash in 3 tbsp of the cooking water. At first, the pasta will look wet and sloppy: keep stirring until the water is absorbed and the sauce is glossy. Check the seasoning before transferring to heated bowls. Sprinkle over some chives or parsley, then serve immediately."
      }
    ],
